CREATE TABLE UPORABNIK(id INT AUTO_INCREMENT PRIMARY KEY, ime VARCHAR(50) NOT NULL, priimek VARCHAR(50) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, geslo_hash VARCHAR(100) NOT NULL, vloga ENUM('admin','ucitelj','ucenec') NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE PREDMET(id INT AUTO_INCREMENT PRIMARY KEY, naziv VARCHAR(100) NOT NULL UNIQUE, opis TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE UCITELJ_PREDMET(uporabnik_id INT NOT NULL, predmet_id INT NOT NULL, PRIMARY KEY(uporabnik_id,predmet_id),
 FOREIGN KEY(uporabnik_id) REFERENCES UPORABNIK(id) ON DELETE CASCADE, FOREIGN KEY(predmet_id) REFERENCES PREDMET(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE VPIS(uporabnik_id INT NOT NULL, predmet_id INT NOT NULL, PRIMARY KEY(uporabnik_id,predmet_id),
 FOREIGN KEY(uporabnik_id) REFERENCES UPORABNIK(id) ON DELETE CASCADE, FOREIGN KEY(predmet_id) REFERENCES PREDMET(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE GRADIVO(id INT AUTO_INCREMENT PRIMARY KEY, predmet_id INT NOT NULL, nalozil_id INT NULL, naslov VARCHAR(150) NOT NULL, pot_datoteke VARCHAR(255) NOT NULL, datum_nalozitve DATETIME DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(predmet_id) REFERENCES PREDMET(id) ON DELETE CASCADE, FOREIGN KEY(nalozil_id) REFERENCES UPORABNIK(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ODDAJA(id INT AUTO_INCREMENT PRIMARY KEY, ucenec_id INT NOT NULL, predmet_id INT NOT NULL, naslov_naloge VARCHAR(150) NOT NULL, pot_datoteke VARCHAR(255) NOT NULL, datum_oddaje DATETIME DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(ucenec_id,predmet_id,naslov_naloge), FOREIGN KEY(ucenec_id) REFERENCES UPORABNIK(id) ON DELETE CASCADE, FOREIGN KEY(predmet_id) REFERENCES PREDMET(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
